Convert SQL to PySpark:
```sql
select id, device, started_at
from (
    select *, row_number() over (partition by device order by started_at, id) as rn
    from sessions
    where hour(started_at) between 8 and 16
) as t
where rn <= 1;
```

Convert SQL to PySpark:
```sql
select *
from (
    select
        dept_id,
        job_title,
        salary
    from employees
) src
pivot (
    max(salary) as amount,
    count(1) as n
    for job_title in ('Designer' as designer, 'Engineer' as engineer)
);
```

Convert SQL to PySpark:
```sql
select *
from (
    select
        order_id,
        method,
        status,
        amount
    from payments
) src
pivot (
    max(amount)
    for status in ('SUCCESS', 'FAILED', 'REFUNDED')
);
```

Convert SQL to PySpark:
```sql
select *
from (
    select
        store_id,
        status,
        amount
    from orders
) src
pivot (
    sum(amount)
    for status in ('RETURNED', 'COMPLETED', 'PENDING')
);
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by product_id order by last_restock, id) as rank_in_group
    from inventory
) t
where rank_in_group = 1;
```

Convert SQL to PySpark:
```sql
select *
from (
    select
        firmware,
        device_code,
        temp_c
    from device_readings
) src
pivot (
    sum(temp_c) as value_sum,
    count(1) as item_count
    for device_code in ('DV-03' as dv_03, 'DV-04' as dv_04, 'DV-02' as dv_02)
);
```

Convert SQL to PySpark:
```sql
SELECT * FROM (
    SELECT segment, country, credit_limit FROM customers
) PIVOT (
    SUM(credit_limit) FOR country IN ('TH', 'US', 'SG')
);
```

Convert SQL to PySpark:
```sql
select *
from (
    select *, row_number() over (partition by city order by rating desc nulls first, id) as row_num
    from suppliers
) ranked
where row_num = 1;
```

Convert SQL to PySpark:
```sql
select sale_cohort, cnt
from (
    select case when year(sale_date) < 2024 then 'before_2024' when year(sale_date) = 2024 then '2024' else 'after_2024' end sale_cohort, count(*) cnt
    from store_sales
    group by case when year(sale_date) < 2024 then 'before_2024' when year(sale_date) = 2024 then '2024' else 'after_2024' end
) x
where cnt >= 9;
```

Convert SQL to PySpark:
```sql
select region, new_york_count, latest_opened_date
from (
    select region, count(case when city = 'New York' then 1 end) as new_york_count, max(opened_date) as latest_opened_date
    from stores
    group by region
) as agg
where new_york_count < 8;
```

Convert SQL to PySpark:
```sql
select *
from (
    select
        promo_code,
        channel,
        discount_pct
    from promotions
) src
pivot (
    avg(discount_pct) as value_sum,
    count(1) as n
    for channel in ('mobile', 'partner')
);
```

Convert SQL to PySpark:
