```

Convert SQL to PySpark:
```sql
select *
from (
    select *, rank() over (partition by status order by end_date desc) as pos
    from subscriptions
) as ranked
where pos <= 3;
```

Convert SQL to PySpark:
```sql
select is_active, country, uk_age
from (
    select is_active, country, sum(case when country = 'UK' then age else 0 end) as uk_age
    from customers
    group by is_active, country
) as s
